#pragma once
// The embedded WGSL shader bank: every program stage the
// web build can bind, converted from its GLSL ES source at build time. Stages
// are zstd frames over a shared dictionary, decompressed at their first use.
// The tables are generated by scripts/web-shader-bank.py.
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

namespace aurora::webgpu::shader_bank {
struct Stage {
  uint64_t key;                  // XXH3-64 of the stage's GLSL ES source
  uint32_t offset, packed, size; // zstd frame in Blob, decompressed WGSL size
};

extern const unsigned char* const Blob; // dictionary, then the frames
extern const uint32_t DictionaryBytes;
extern const Stage VertexStages[];
extern const Stage FragmentStages[];
extern const size_t VertexStageCount;
extern const size_t FragmentStageCount;

// A sampled texture of a stage: group 1, texture binding 2 * slot, sampler
// binding 2 * slot + 1. kind 'f', 'i' or 'u'; sampled: read with a sampler
// (filtering), otherwise only loaded.
struct Texture {
  std::string name;
  char kind = 'f';
  bool sampled = false;
};

struct Module {
  std::string wgsl;
  std::vector<std::pair<std::string, uint32_t>> blocks; // uniform block -> group 0 binding
  std::vector<std::string> loose;                       // loose vec4 uniforms, 16 bytes apart
  std::vector<Texture> textures;                        // by slot
};

// The banked stage, or false when the bank has none.
bool find(uint64_t key, bool fragment, Module& out);
} // namespace aurora::webgpu::shader_bank
